import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.CVVTRPFj.js";const u=JSON.parse('{"title":"Yamapper — справка","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1795455254000}'),i={name:"index.md"};function n(l,a,p,s,d,h){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="yamapper-—-справка" tabindex="-1">Yamapper — справка <a class="header-anchor" href="#yamapper-—-справка" aria-label="Permalink to &quot;Yamapper — справка&quot;">​</a></h1><p>Расширение для браузера <strong>Yamapper</strong> загружает геоданные в <a href="https://yandex.ru/support/nmaps/ru/map-blocknot.html" target="_blank" rel="noreferrer">Блокнот картографа</a> редактора <a href="https://n.maps.yandex.ru/" target="_blank" rel="noreferrer">Народной карты Яндекс</a>: конвертирует Shapefile, GeoJSON, GPX, KML, KMZ, TopoJSON и WKT в формат блокнота и сохраняет их на Яндекс Диск.</p><h2 id="что-умеет" tabindex="-1">Что умеет <a class="header-anchor" href="#что-умеет" aria-label="Permalink to &quot;Что умеет&quot;">​</a></h2><ul><li><strong>Конвертация</strong> — Shapefile, GeoJSON, GPX, KML, KMZ, TopoJSON, WKT → формат Блокнота картографа.</li><li><strong>Загрузка</strong> — данные автоматически попадают в <code>Приложения/Блокнот картографа Народной карты</code>, по папкам с датой загрузки.</li><li><strong>Геометрии</strong> — Point, MultiPoint, LineString, MultiLineString, Polygon, MultiPolygon, GeometryCollection.</li><li><strong>Раздельный вид</strong> — редактор и Nakarte в одном окне.</li><li><strong>НСПД</strong> — загрузка АТД из Национальной системы пространственных данных.</li><li><strong>Заметки</strong> — управление загруженными данными прямо в нижней панели редактора.</li></ul><h2 id="куда-идти-дальше" tabindex="-1">Куда идти дальше <a class="header-anchor" href="#куда-идти-дальше" aria-label="Permalink to &quot;Куда идти дальше&quot;">​</a></h2><ul><li>Впервые ставите расширение? Начните с <a href="/yamapper/guide/">установки</a> и <a href="/yamapper/guide/first-upload">первой загрузки</a>.</li><li>Не уверены, что ваш файл подойдёт? Смотрите <a href="/yamapper/guide/formats">поддерживаемые форматы</a>.</li><li>Собираете расширение из исходников? Переходите в раздел <a href="/yamapper/dev/">разработчикам</a>.</li></ul>',6)])])}const g=e(i,[["render",n]]);export{u as __pageData,g as default};
